#!/usr/bin/env node
/**
 * src/lib/email/templates/*.html  ->  src/lib/email/templates.generated.ts
 *
 * The templates are authored and reviewed as HTML files - that is the form a
 * designer can open, and the form an e-mail client actually receives. But the
 * send path runs on serverless, where reading a file off disk at request time
 * is the one thing that is not reliably there, so the HTML is compiled into a
 * plain string map and the generated file is committed.
 *
 * Run `npm run email:build` after editing any template; `prebuild` and
 * `predev` run it too, and `templates.test.ts` fails if the committed output
 * has drifted from the sources.
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const DIR = join(process.cwd(), "src", "lib", "email", "templates");
const OUT = join(
  process.cwd(),
  "src",
  "lib",
  "email",
  "templates.generated.ts",
);

/** `data-subject="…"` off the outer table. */
function attr(html, name) {
  const m = html.match(new RegExp(`\\sdata-${name}="([^"]*)"`));
  return m ? m[1] : "";
}

export function buildSource() {
  const files = readdirSync(DIR)
    .filter((f) => f.endsWith(".html"))
    .sort();

  const entries = files.map((file) => {
    const html = readFileSync(join(DIR, file), "utf8");
    const name = file.replace(/\.html$/, "");
    return {
      name,
      subject: attr(html, "subject"),
      preheader: attr(html, "preheader"),
      commercial: attr(html, "commercial") === "1",
      html,
    };
  });

  const missing = entries.filter((e) => !e.subject);
  if (missing.length > 0) {
    throw new Error(
      `data-subject eksik: ${missing.map((e) => e.name).join(", ")}`,
    );
  }

  const body = entries
    .map(
      (e) => `  ${JSON.stringify(e.name)}: {
    subject: ${JSON.stringify(e.subject)},
    preheader: ${JSON.stringify(e.preheader)},
    commercial: ${e.commercial},
    html: ${JSON.stringify(e.html)},
  },`,
    )
    .join("\n");

  buildSource.count = entries.length;

  return `// GENERATED by scripts/build-email-templates.mjs - do not edit.
// Source: src/lib/email/templates/*.html · npm run email:build

export interface EmailTemplate {
  /** Subject line, still carrying its own [FIELD]s. */
  subject: string;
  /** Preview text; already inside the HTML too, kept here for the text part. */
  preheader: string;
  /** 6563 ticari ileti - these and only these carry an unsubscribe link. */
  commercial: boolean;
  html: string;
}

export const EMAIL_TEMPLATES: Record<string, EmailTemplate> = {
${body}
};

export type EmailTemplateName = ${entries
    .map((e) => JSON.stringify(e.name))
    .join(" | ")};
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const source = buildSource();
  writeFileSync(OUT, source, "utf8");
  console.log(
    `[email] ${buildSource.count} şablon derlendi → templates.generated.ts`,
  );
}
